/**
 * Reproduces the 2026-08-16 theme-benchmark correctness failure on LIBRARY query 3 ("Library: loans due after Jan 10"):
 * a COUNT(DISTINCT ?loan) over OPTIONAL dueDate + date FILTER + MINUS that must return
 * {@link ThemeQueryCatalog#expectedCountFor} = 7958 but returned 7959 (janino off) and 7956 (janino on) on the very
 * first execution against the benchmark-scale LIBRARY dataset. The store is loaded exactly like the benchmark loads a
 * theme: one {@link IsolationLevels#NONE} transaction over {@link ThemeDataSetGenerator#generate}.
 */
class LmdbLibraryLoanCountRegressionTest {

	private static final String JANINO_ENABLED = "rdf4j.lmdb.janinoCodegen.enabled";
	private static final String JANINO_THRESHOLD_ROWS = "rdf4j.lmdb.janinoCodegen.thresholdRows";
	private static final String JANINO_SYNCHRONOUS = "rdf4j.lmdb.janinoCodegen.synchronous";

	@ParameterizedTest(name = "janinoEnabled={0}")
	@ValueSource(strings = { "false", "true" })
	void libraryQuery3CountMatches(String janinoEnabled, @TempDir Path dataDir) throws Exception {
		String previousEnabled = System.getProperty(JANINO_ENABLED);
		String previousThreshold = System.getProperty(JANINO_THRESHOLD_ROWS);
		String previousSynchronous = System.getProperty(JANINO_SYNCHRONOUS);
		System.setProperty(JANINO_ENABLED, janinoEnabled);
		System.setProperty(JANINO_THRESHOLD_ROWS, "0");
		System.setProperty(JANINO_SYNCHRONOUS, "true");
		try {
			LmdbStore store = new LmdbStore(dataDir.resolve("library").toFile(), ConfigUtil.createConfig());
			SailRepository repository = new SailRepository(store);
			try {
				try (SailRepositoryConnection connection = repository.getConnection()) {
					connection.begin(IsolationLevels.NONE);
					ThemeDataSetGenerator.generate(ThemeDataSetGenerator.Theme.LIBRARY, new RDFInserter(connection));
					connection.commit();
				}
				long expected = ThemeQueryCatalog.expectedCountBindingValueFor(ThemeDataSetGenerator.Theme.LIBRARY, 3)
						.orElseThrow();
				String query = ThemeQueryCatalog.queryFor(ThemeDataSetGenerator.Theme.LIBRARY, 3);
				// The benchmark failure was a rare race (a shared value-decode cache corrupted by concurrent parallel
				// kernel workers), so hammer the query: at benchmark scale the parallel aggregate route deviated
				// roughly once per couple hundred executions before the LmdbNativeValueCodec fix.
				for (int i = 0; i < 300; i++) {
					Assertions.assertEquals(expected, executeCount(repository, query),
							"execution " + i + ", janinoEnabled=" + janinoEnabled);
				}
			} finally {
				repository.shutDown();
			}
		} finally {
			restore(JANINO_ENABLED, previousEnabled);
			restore(JANINO_THRESHOLD_ROWS, previousThreshold);
			restore(JANINO_SYNCHRONOUS, previousSynchronous);
		}
	}

	private static long executeCount(SailRepository repository, String query) {
		try (SailRepositoryConnection connection = repository.getConnection();
				TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
			Assertions.assertTrue(result.hasNext(), "aggregate query must produce one row");
			BindingSet row = result.next();
			Value count = row.getValue("count");
			Assertions.assertInstanceOf(Literal.class, count, "?count must be a literal but was: " + count);
			Assertions.assertFalse(result.hasNext(), "aggregate query must produce exactly one row");
			return ((Literal) count).longValue();
		}
	}

	private static void restore(String property, String previousValue) {
		if (previousValue == null) {
			System.clearProperty(property);
		} else {
			System.setProperty(property, previousValue);
		}
	}
}
